import{_ as o,o as t,c as r,a2 as a}from"./chunks/framework.G0y0PQA7.js";const h=JSON.parse('{"title":"Start from SQL or DBML","description":"","frontmatter":{},"headers":[],"relativePath":"en/quick/import-start.md","filePath":"en/quick/import-start.md"}'),n={name:"en/quick/import-start.md"};function s(i,e,d,l,m,c){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="start-from-sql-or-dbml" tabindex="-1">Start from SQL or DBML <a class="header-anchor" href="#start-from-sql-or-dbml" aria-label="Permalink to &quot;Start from SQL or DBML&quot;">​</a></h1><p>Create a new model from SQL (<code>CREATE TABLE</code>), DBML, Mermaid or Markdown files exported from another tool or a database dump. No database connection is needed.</p><ol><li><strong>Open the import dialog</strong> — Choose File › Import › From SQL, DBML, Mermaid or Markdown…. No document needs to be open. Dragging an <code>.sql</code>, <code>.dbml</code>, <code>.mmd</code> or <code>.md</code> file onto the window opens the same dialog.</li><li><strong>Choose the input</strong> — Choose <strong>File</strong> and pick a file with <strong>Browse…</strong>, or choose <strong>Paste</strong> and paste the text as it is. The format and SQL dialect are detected automatically, so you can usually leave them alone.</li><li><strong>Import into</strong> — Choose <strong>New document</strong>. To add to a model you already have open, choose <strong>Merge into the current document</strong>.</li><li><strong>Preview</strong> — Check how many tables, columns, relationships and indexes were found, and any warnings. Statements that cannot be read are skipped with a warning.</li><li><strong>Import</strong> — The model opens in a new untitled tab. Tidy up the table positions, then press <kbd>Ctrl</kbd>+<kbd>S</kbd> to save it as an <code>.erm</code> file.</li></ol><div class="tip custom-block"><p class="custom-block-title">Tip</p><p>A merge into the current document is undone in one step with <kbd>Ctrl</kbd>+<kbd>Z</kbd>. For objects whose names already exist, choose Overwrite, Skip or Add with a new name.</p></div><p>To connect to a live database and import its structure, see <a href="/relio/en/quick/database">Import from and apply to a database</a>.</p><p><strong>More</strong> → <a href="/relio/en/features/import">Import and other formats</a> · <a href="/relio/en/features/cli#relio-import">Command line › relio import</a></p>',6)])])}const u=o(n,[["render",s]]);export{h as __pageData,u as default};
